+#[must_use]
+pub fn cutter_depth_limit(params: &OpParams, tool: &Tool) -> f64 {
+    let radius = tool.diameter * 0.5;
+    if matches!(params, OpParams::VCarve { .. }) {
+        if !(tool.tip_angle > 0.0 && tool.tip_angle < 180.0) {
+            return 0.0;
+        }
+        radius / (tool.tip_angle.to_radians() * 0.5).tan()
