+#[test]
+fn the_letter_matches_its_golden_cl_file() {
+    let (world, mut h) = job();
+    let tp = generated(&world, &mut h, carve(TOP, 1.0, true));
+    common::write_golden("v_carve_letter_l.cl", &common::gen_to_cltext(&tp.path));
+}
