+/// A 90 degree V-bit, 12 mm wide: the cut is as deep as it is wide on
+/// each side, so the numbers below read off the drawing.
+fn params() -> VCarveParams {
+    VCarveParams {
+        angle_deg: 90.0,
+        tool_diameter: 12.0,
+        clearance_z: 10.0,
+        retract_z: Some(3.0),
+        top_z: TOP,
+        bottom_z: -6.0,
+        stepdown: 6.0,
+        feed: 600.0,
+        plunge_feed: 200.0,
+        flat_clear: false,
+        flat_stepover: 0.25,
